			"msoAnimAccumulateAlways": {"name":"msoAnimAccumulateAlways","type":"MsoAnimAccumulate","value":2,"source":"external","doc":{"summary":"Accumulates with other animation behaviors.","params":[],"source":"external"}},
			"msoAnimAccumulateNone": {"name":"msoAnimAccumulateNone","type":"MsoAnimAccumulate","value":1,"source":"external","doc":{"summary":"Does not accumulate.","params":[],"source":"external"}},
			"msoAnimAdditiveAddBase": {"name":"msoAnimAdditiveAddBase","type":"MsoAnimAdditive","value":1,"source":"external","doc":{"summary":"Uses the animation behavior of the base animations.","params":[],"source":"external"}},
			"msoAnimAdditiveAddSum": {"name":"msoAnimAdditiveAddSum","type":"MsoAnimAdditive","value":2,"source":"external","doc":{"summary":"Adds together the animation behavior of multiple animations.","params":[],"source":"external"}},
			"msoAnimAfterEffectDim": {"name":"msoAnimAfterEffectDim","type":"MsoAnimAfterEffect","value":1,"source":"external","doc":{"summary":"Dimmed","params":[],"source":"external"}},
			"msoAnimAfterEffectHide": {"name":"msoAnimAfterEffectHide","type":"MsoAnimAfterEffect","value":2,"source":"external","doc":{"summary":"Hidden","params":[],"source":"external"}},
			"msoAnimAfterEffectHideOnNextClick": {"name":"msoAnimAfterEffectHideOnNextClick","type":"MsoAnimAfterEffect","value":3,"source":"external","doc":{"summary":"Hidden on the next mouse click","params":[],"source":"external"}},
			"msoAnimAfterEffectMixed": {"name":"msoAnimAfterEffectMixed","type":"MsoAnimAfterEffect","value":-1,"source":"external","doc":{"summary":"Mixed","params":[],"source":"external"}},
			"msoAnimAfterEffectNone": {"name":"msoAnimAfterEffectNone","type":"MsoAnimAfterEffect","value":0,"source":"external","doc":{"summary":"Unchanged","params":[],"source":"external"}},
